import{_ as t,c as o,o as a,a3 as r}from"./chunks/framework.Dokpd4od.js";const c=JSON.parse('{"title":"Employees","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/employees/employees/index.md","filePath":"master/human-resources/employees/employees/index.md","lastUpdated":1792041590000}'),s={name:"master/human-resources/employees/employees/index.md"};function l(n,e,i,p,d,h){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="employees" tabindex="-1">Employees <a class="header-anchor" href="#employees" aria-label="Permalink to &quot;Employees&quot;">​</a></h1><p>An employee record is the single place where Aureus keeps everything about one person who works for your company. It holds contact details, who they report to, where and when they work, private information, skills and past experience. Other apps, such as Time Off and Recruitment, read from this record.</p><blockquote><p><strong>In simple words:</strong> An employee record is the file you keep for each team member.</p></blockquote><div class="info custom-block"><p class="custom-block-title">Employee or user?</p><p>An employee is the HR file of a person. A user is a login to Aureus. One person can have both. Link them with <strong>Related User</strong>.</p></div><p>Open <code>Employees → Employees</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>Create the <a href="./../departments/departments.html">department</a>, the <a href="./../setup/job-positions.html">job position</a> and the <a href="./../setup/tags.html">tags</a> you want to use. You can start without them, because only <strong>Name</strong> is required.</p></div><h2 id="how-the-pieces-connect" tabindex="-1">How the pieces connect <a class="header-anchor" href="#how-the-pieces-connect" aria-label="Permalink to &quot;How the pieces connect&quot;">​</a></h2><p>One record is split into small parts. Each part has its own page in this guide.</p><ul><li><strong>Profile:</strong> the top block with name, job title, photo, department, job position, manager, coach and tags. See <a href="./employee-profile.html">Employee profile</a>.</li><li><strong>Work Information:</strong> work address and location, approvers, working hours, time zone, company and colour. See <a href="./add-employee.html">Add an employee</a>.</li><li><strong>Private Information:</strong> home address, emergency contact, family status, education, citizenship and work permit.</li><li><strong>Settings:</strong> active status, related user, departure reason, language, notes, Badge ID and PIN.</li><li><strong>Skills and resume:</strong> what the person can do and where they worked or studied. See <a href="./skills-and-resume.html">Skills and resume</a>.</li></ul><p>Each part is saved on the same record. You fill them on the form, and you read them on the profile page.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Page</th></tr></thead><tbody><tr><td>Create a new employee</td><td><a href="./add-employee.html">Add an employee</a></td></tr><tr><td>Read or change a record</td><td><a href="./employee-profile.html">Employee profile</a></td></tr><tr><td>Find, filter and group employees</td><td><a href="./employee-list.html">Employee list</a></td></tr><tr><td>Record skills and past experience</td><td><a href="./skills-and-resume.html">Skills and resume</a></td></tr><tr><td>Record a departure</td><td><a href="./leaving-the-company.html">Leaving the company</a></td></tr></tbody></table><h2 id="how-employees-link-to-other-records" tabindex="-1">How employees link to other records <a class="header-anchor" href="#how-employees-link-to-other-records" aria-label="Permalink to &quot;How employees link to other records&quot;">​</a></h2><ul><li><strong>Department, job position, tags and work location</strong> come from lists you maintain in <a href="./../setup/">Setup</a>.</li><li><strong>Manager and coach</strong> are other employees. The manager is the person this employee reports to.</li><li><strong>Related user</strong> links the employee to a login. The user can then sign in to Aureus.</li><li><strong>Contact:</strong> Aureus keeps a matching contact for every employee. See <a href="./add-employee.html">Add an employee</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Create employees in this order: department, job position, then the employee. The employee form can then pick them from a list.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./add-employee.html">Add an employee</a></li><li><a href="./employee-list.html">Employee list</a></li><li><a href="./../departments/departments.html">Departments</a></li><li><a href="./../reporting/skills-report.html">Skills report</a></li></ul>',17)]))}const u=t(s,[["render",l]]);export{c as __pageData,u as default};
